void draw_player(Player * p, int32_t cam_x) {
    __auto_type px = (int32_t)p->x;
    __auto_type py = (int32_t)p->y;
    __auto_type sx = (px - cam_x);
    if (((sx + PLAYER_W) < 0) || (sx > SCREEN_W)) {
        return;
    }
    uint32_t color = COLOR_PLAYER;
    switch (p->state) {
        case PlayerState_idle:
        {
            color = 0xFF4444FF;
            break;
        }
        case PlayerState_running:
        {
            color = 0xFF6622FF;
            break;
        }
        case PlayerState_jumping:
        {
            color = 0xFFAA00FF;
            break;
        }
        case PlayerState_falling:
        {
            color = 0xFF8844FF;
            break;
        }
        case PlayerState_landing:
        {
            color = 0xFFFFAAFF;
            break;
        }
    }
    rdpq_set_fill_color(color);
    rdpq_fill_rectangle(sx, py, (sx + PLAYER_W), (py + PLAYER_H));
    rdpq_set_fill_color(0xFFFFFFFF);
    if (p->facing_right) {
        rdpq_fill_rectangle((sx + 8), (py + 4), (sx + 10), (py + 6));
    }
    else {
        rdpq_fill_rectangle((sx + 2), (py + 4), (sx + 4), (py + 6));
    }
}

void draw_pickup(Pickup p, int32_t cam_x) {
    switch (p.tag) {
        case Pickup_tag_coin:
        {
            __auto_type cx = p.data.coin.field0;
            __auto_type cy = p.data.coin.field1;
            __auto_type sx = (cx - cam_x);
            if ((sx < -8) || (sx > SCREEN_W)) {
                return;
            }
            rdpq_set_fill_color(COLOR_COIN);
            rdpq_fill_rectangle((sx - 4), (cy - 4), (sx + 4), (cy + 4));
            break;
        }
        case Pickup_tag_empty:
        {
            break;
        }
    }
}

void draw_pickups(int32_t cam_x) {
    int32_t i = 0;
    while (i < MAX_COINS) {
        draw_pickup(pickups[i], cam_x);
        i += 1;
    }
}

void draw_hud(GameState * gs) {
    int32_t i = 0;
    while (i < gs->player.health) {
        __auto_type hx = (8 + (i * 14));
        rdpq_set_fill_color(0xFF2222FF);
        rdpq_fill_rectangle(hx, 8, (hx + 10), 16);
        i += 1;
    }
    __auto_type bar_w = gs->player.score;
    if (bar_w > 200) {
        bar_w = 200;
    }
    if (bar_w > 0) {
        rdpq_set_fill_color(0xFFDD44FF);
        rdpq_fill_rectangle(8, 20, (8 + bar_w), 26);
    }
}

void update_playing(GameState * gs, joypad_status_t pad) {
    gs->player.handle_input(pad);
    gs->player.physics();
    gs->player.resolve_collisions();
    gs->player.update_state();
    gs->player.collect_pickups();
    gs->camera.follow(gs->player.x);
    if (pad.pressed.start) {
        gs->phase = GamePhase_paused;
    }
    if (gs->player.health <= 0) {
        gs->phase = GamePhase_gameover;
    }
    gs->frame += 1;
}

void update_title(GameState * gs, joypad_status_t pad) {
    if (pad.pressed.start || pad.pressed.a) {
        gs->phase = GamePhase_playing;
    }
}

void update_paused(GameState * gs, joypad_status_t pad) {
    if (pad.pressed.start) {
        gs->phase = GamePhase_playing;
    }
}

void update_gameover(GameState * gs, joypad_status_t pad) {
    if (pad.pressed.start || pad.pressed.a) {
        gs->player.init();
        gs->camera.init();
        gs->frame = 0;
        gs->coins_collected = 0;
        init_platforms();
        init_pickups();
        gs->phase = GamePhase_title;
    }
}

void update(GameState * gs, joypad_status_t pad) {
    switch (gs->phase) {
        case GamePhase_title:
        {
            update_title(gs, pad);
            break;
        }
        case GamePhase_playing:
        {
            update_playing(gs, pad);
            break;
        }
        case GamePhase_paused:
        {
            update_paused(gs, pad);
            break;
        }
        case GamePhase_gameover:
        {
            update_gameover(gs, pad);
            break;
        }
    }
}

void render_world(GameState * gs) {
    __auto_type cam_x = gs->camera.offset;
    rdpq_set_mode_fill(COLOR_SKY);
    rdpq_fill_rectangle(0, 0, SCREEN_W, SCREEN_H);
    rdpq_sync_pipe();
    draw_platforms(cam_x);
    rdpq_sync_pipe();
    draw_pickups(cam_x);
    rdpq_sync_pipe();
    draw_player(&gs->player, cam_x);
    rdpq_sync_pipe();
    draw_hud(gs);
}

void render_title(void) {
    rdpq_set_mode_fill(0x1A1A4AFF);
    rdpq_fill_rectangle(0, 0, SCREEN_W, SCREEN_H);
    rdpq_sync_pipe();
    rdpq_set_mode_fill(0xFF4444FF);
    rdpq_fill_rectangle(60, 80, 260, 100);
    rdpq_sync_pipe();
    rdpq_set_mode_fill(0xFFFFFFFF);
    rdpq_fill_rectangle(100, 150, 220, 160);
}

void render_paused(GameState * gs) {
    render_world(gs);
    rdpq_sync_pipe();
    rdpq_set_mode_fill(0x00000088);
    rdpq_fill_rectangle(80, 100, 240, 140);
    rdpq_sync_pipe();
    rdpq_set_mode_fill(0xFFFFFFFF);
    rdpq_fill_rectangle(100, 112, 220, 120);
}

void render_gameover(void) {
    rdpq_set_mode_fill(0x220000FF);
    rdpq_fill_rectangle(0, 0, SCREEN_W, SCREEN_H);
    rdpq_sync_pipe();
    rdpq_set_mode_fill(0xFF2222FF);
    rdpq_fill_rectangle(60, 100, 260, 130);
    rdpq_sync_pipe();
    rdpq_set_mode_fill(0xFFFFFFFF);
    rdpq_fill_rectangle(100, 160, 220, 170);
}

void render(GameState * gs) {
    __auto_type fb = display_get();
    rdpq_attach_clear(fb);
    switch (gs->phase) {
        case GamePhase_title:
        {
            render_title();
            break;
        }
        case GamePhase_playing:
        {
            render_world(gs);
            break;
        }
        case GamePhase_paused:
        {
            render_paused(gs);
            break;
        }
        case GamePhase_gameover:
        {
            render_gameover();
            break;
        }
    }
    rdpq_detach_show();
}

int main(void) {
    display_init(0, 2, 3, 0, 1);
    rdpq_init();
    joypad_init();
    timer_init();
    GameState gs; /* undefined */
    gs.player.init();
    gs.camera.init();
    gs.phase = GamePhase_title;
    gs.frame = 0;
    gs.coins_collected = 0;
    init_platforms();
    init_pickups();
    while (true) {
        joypad_poll();
        __auto_type pad = joypad_get_status(0);
        update(&gs, pad);
        render(&gs);
    }
    rdpq_close();
    debugf("platformer: shutdown");
    return 0;
}

